changeSet.sql:
ALTER TABLE campo_ficha ADD CONSTRAINT ck_campo_ficha_tipo
CHECK (tipo IN ('TEXTO', 'TEXTO_LONGO', 'CHECKBOX', 'DATA',
                'NUMERO', 'OPCOES', 'MULTIPLAS_OPCOES'));

ALTER TABLE campo_ficha ADD CONSTRAINT ck_campo_ficha_opcoes
CHECK (tipo NOT IN ('OPCOES', 'MULTIPLAS_OPCOES')
       OR (opcoes IS NOT NULL AND length(btrim(opcoes)) > 0));

ALTER TABLE ficha_anamnese DROP CONSTRAINT fk_ficha_anamnese_modelo;
ALTER TABLE ficha_anamnese ADD CONSTRAINT fk_ficha_anamnese_modelo
FOREIGN KEY (modelo_id) REFERENCES modelo_ficha(id) ON DELETE SET NULL;

ALTER TABLE resposta_ficha DROP CONSTRAINT fk_resposta_ficha_campo;
ALTER TABLE resposta_ficha ADD CONSTRAINT fk_resposta_ficha_campo
FOREIGN KEY (campo_id) REFERENCES campo_ficha(id) ON DELETE SET NULL;

ALTER TABLE resposta_ficha ADD CONSTRAINT ck_resposta_ficha_tipo
CHECK (tipo IN ('TEXTO', 'TEXTO_LONGO', 'CHECKBOX', 'DATA',
                'NUMERO', 'OPCOES', 'MULTIPLAS_OPCOES'));
